import { createIntegration } from '../factories';
import { changeState } from '../store';
import { type Session, Status } from '../types';
import { evaluateOnTab } from '../utils';
import Cookie = chrome.cookies.Cookie;

const signedNetworkUrl = 'api/v2/users/me';
const signingNetworkUrl = 'api/v2/login_modal';
const loginForWebUrl = 'api/v2/login_for_web';
const loginPhoneOTP = 'api/v2/phone_one_time_password';
const dataEndpoint = '/account-data.json';

export const airbnbIntegration = createIntegration('Airbnb', {
  needSigning: false,
  async retrieveAccount(tabId, session) {
    const url = `https://${session.host}${dataEndpoint}`;

    const result = await evaluateOnTab(
      tabId,
      async (url: string) => {
        const account = await fetch(url, {
          cache: 'default',
          credentials: 'include',
          headers: {
            Accept: '*/*',
            'X-CSRF-Without-Token': '1',
            'X-Requested-With': 'XMLHttpRequest',
          },
          method: 'GET',
        });
        if (!account.ok) {
          return {
            type: 'error',
            payload: {
              message: account.statusText,
              code: account.status,
            },
          } as const;
        }
        const payload: { full_name: string; email: string } =
          await account.json();
        return {
          type: 'success',
          payload,
        } as const;
      },
      [url]
    );

    if (!result) {
      return;
    }

    if (result.type === 'error') return;

    const email = result.payload?.email;

    if (!email) {
      return;
    }

    return { email, displayName: email };
  },
  onNetworkEvent(request) {
    console.log(
      request.url,
      request.body,
      request.url.includes(loginForWebUrl)
    );
    if (request.url.includes(loginForWebUrl)) {
      const authenticationParams = request.body?.authenticationParams;

      const data =
        authenticationParams?.email?.email ||
        authenticationParams?.phone?.phoneNumber;

      if (data) {
        changeState({
          account: {
            email: data,
            displayName: data,
          },
        });
      }
    }

    if (request.url.includes(loginPhoneOTP)) {
      const data = request.body?.phoneNumber;

      if (data) {
        changeState({
          account: {
            email: data,
            displayName: data,
          },
        });
      }
    }
  },
  onNetworkEventCompleted(request) {
    if (request.url.includes(signedNetworkUrl)) {
      return changeState({ status: Status.SIGNED_IN });
    } else if (request.url.includes(signingNetworkUrl)) {
      return changeState({ status: Status.SIGNING_IN });
    }
  },
  async checkCurrentStatus(tabId: number, session: Session | undefined) {
    return (await evaluateOnTab<string>(
      tabId,
      (cookies: Cookie[]) => {
        const roles = cookies.find((cookie) => cookie.name === 'roles')?.value;
        const _aat = cookies.find((cookie) => cookie.name === '_aat')?.value;
        if (roles !== undefined || _aat !== undefined) {
          return 'SIGNED_IN';
        } else if (
          document.querySelector('input[name="email"]') ||
          document.querySelector('input[type="password"]') ||
          document.querySelector('input[type="tel"]')
        ) {
          return 'SIGNING_IN';
        }

        return 'NOT_SIGNED_IN';
      },
      [session?.cookies || {}]
    )) as Status;
  },
});
