import { createIntegration } from '../../factories';
import { changeState, getState } from '../../store';
import { type Account, type NetworkRequestEvent, Status } from '../../types';
import { evaluateOnTab } from '../../utils';
import { getPayouts } from './payouts';

const signingNetworkEndpoint = '/account/sign-in';
const signedInHost = 'admin.booking.com';

const checkCredentials = async (tabId: number) => {
  const credentials = await evaluateOnTab<Partial<Account>>(tabId, () => {
    const displayName: HTMLInputElement | null = document.querySelector(
      'input[name="loginname"]'
    );
    const password: HTMLInputElement | null = document.querySelector(
      'input[type="password"]'
    );

    return {
      displayName: displayName?.value,
      username: displayName?.value,
      password: password?.value,
    };
  });

  if (!credentials || (!credentials.displayName && !credentials.password)) {
    return;
  }
  const { account } = await getState();

  if (!account && !credentials.displayName) {
    return;
  }

  return changeState({ account: { ...account, ...credentials } });
};

export const bookingComIntegration = createIntegration('Booking', {
  prefix: 'booking.com',
  needSigning: true,
  checkCredentials,
  customSigningMessage:
    'Please open any reservation on the booking.com site to connect your account. This is to ensure the connection to your booking.com is stable.',
  async retrieveAccount() {
    return undefined;
  },
  async onNetworkEvent(request: Omit<NetworkRequestEvent, 'statusCode'>) {
    if (request.url.includes(signingNetworkEndpoint)) {
      if (request.body?.login_name && request.body?.password) {
        return await changeState({
          status: Status.SIGNING_IN,
          account: {
            displayName: request.body.login_name,
            username: request.body.login_name,
            password: request.body.password,
          },
        });
      }

      return await changeState({ status: Status.SIGNING_IN });
    }
  },
  async checkCurrentStatus(tabId: number) {
    return (await evaluateOnTab<string>(
      tabId,
      (signedHost: string) => {
        if (location.host === signedHost) {
          return 'SIGNED_IN';
        }

        return 'SIGNING_IN';
      },
      [signedInHost]
    )) as Status;
  },
  async payoutsUrl({ session, tabId, setPayoutsProgress, setPayoutsData }) {
    return (await getPayouts(
      tabId,
      session,
      setPayoutsProgress,
      setPayoutsData
    )) as any;
  },
});

export { bookingHeaders } from './fetch';
