import type { Account } from './credentials.types';
import type { Session } from './session.types';

export enum Status {
  NOT_ACTIVE = 'NOT_ACTIVE',
  SIGNED_IN = 'SIGNED_IN',
  SIGNING_IN = 'SIGNING_IN',
  NOT_SIGNED_IN = 'NOT_SIGNED_IN',
}

export type StateProps = {
  // User
  accessToken?: string;
  userId?: string;
  teamId?: string;

  // State
  integration?: string;
  status?: Status;
  session?: Session | undefined;
  tabId?: number;
  account?: Account | undefined;
};

export type StateStore = {
  changeState: StateChange;
} & StateProps;

export type StateChange = (props: StateProps) => Promise<void>;
