import { type StateProps, type StateStore, Status } from '../types';

export const getState = async () => {
  const state: StateProps = await chrome.storage.local.get();
  return {
    ...state,
    changeState,
  } as StateStore;
};

export const clearState = async () => chrome.storage.local.clear();

export const changeState: StateStore['changeState'] = async (newProps) =>
  chrome.storage.local.set(newProps);

export const inactiveState = async (tabId: number | undefined) => {
  // Clearing here to remove integration and session storages
  await chrome.storage.local.remove([
    'integration',
    'session',
    'credentials',
    'account',
  ]);

  return changeState({
    tabId,
    status: Status.NOT_ACTIVE,
  });
};
