import { day } from '@vrplatform/utils';
import type { Session } from '../../../types';
import { evaluateOnTab } from '../../../utils';
import { fetchBooking } from '../fetch';
import { getSinglePayout } from './single.payout';

const fetchPropertiesMutation = () => ({
  operationName: 'propertyListv2',
  variables: {
    input: {
      viewType: 'MULTI_PROPERTY',
      pagination: { offset: 0, rowsPerPage: 1000 },
    },
  },
  extensions: {},
  query:
    'query propertyListv2($input: PropertyListInput\u0021) {\n  partnerProperty {\n    propertyListv2(input: $input) {\n       properties {\n        id\n, name\n        }\n     }\n  }\n}\n',
});

function sleep(ms: number) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function fetchWithRetry(
  url: string,
  options: RequestInit,
  retries = 3,
  delay = 2500
) {
  for (let i = 0; i < retries; i++) {
    try {
      const response = await fetch(url, options);
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      return response;
    } catch (error) {
      if (i === retries - 1) throw error;
      await sleep(delay * 2 ** i); // exponential backoff
    }
  }
}

export async function getPayouts(
  tabId: number,
  session: Session | undefined,
  setPayoutsProgress: (progress: {
    total: number;
    progress: number;
    message: string;
  }) => void,
  setPayoutsData: (data: string) => void
) {
  const sessionId = (await evaluateOnTab<string>(tabId, () => {
    const x = new URLSearchParams(window.location.search);
    return x.get('ses')!;
  })) as string;

  const cookieString = session?.cookies.reduce((acc, curr) => {
    acc += `${curr.name}=${curr.value}; `;
    return acc;
  }, '');

  console.log('cookieString', cookieString, sessionId);

  if (!cookieString) return;

  const properties = await fetchBooking(
    fetchPropertiesMutation(),
    sessionId,
    cookieString
  );

  const propertiesData: {
    data: {
      partnerProperty: {
        propertyListv2: { properties: { id: string; name: string }[] };
      };
    };
  } = await properties.json();

  console.log('PROPERTIES', propertiesData);

  if (
    propertiesData.data.partnerProperty.propertyListv2.properties.length === 1
  ) {
    return getSinglePayout(
      sessionId,
      cookieString,
      setPayoutsData,
      setPayoutsProgress
    );
  }

  let progress = 0;
  for (const property of propertiesData.data.partnerProperty.propertyListv2
    .properties) {
    try {
      setPayoutsProgress({
        total:
          propertiesData.data.partnerProperty.propertyListv2.properties.length,
        progress: ++progress,
        message: `Fetching payouts for property ${property.name}`,
      });

      const fromDate = day().subtract(3, 'month').startOf('month').yyyymmdd();
      const toDate = day().yyyymmdd();
      const url = `https://admin.booking.com/fresa/payment/payout/historyCSV?hotel_id=${property.id}&ses=${sessionId}&year=${day().year()}&from_date=${fromDate}&to_date=${toDate}`;

      const csv = await fetchWithRetry(url, {
        headers: { Cookie: cookieString },
      });

      if (!csv) {
        setPayoutsProgress({
          total:
            propertiesData.data.partnerProperty.propertyListv2.properties
              .length,
          progress,
          message: `No data for property ${property.name}`,
        });
        continue;
      }

      const csvData = await csv.json<{ data: string }>();

      if (!csvData.data) {
        setPayoutsProgress({
          total:
            propertiesData.data.partnerProperty.propertyListv2.properties
              .length,
          progress,
          message: `No data for property ${property.name}`,
        });
        continue;
      }

      console.log('CSV DATA', csvData.data);

      setPayoutsData(csvData.data);
    } catch (error) {
      console.error(error);
    }
  }
}
