import type { ServiceDescriptor } from '../types';
import { airbnbIntegration } from './airbnb.integration';
import { bookingComIntegration } from './booking-com';

export const services: Array<ServiceDescriptor> = [
  {
    matchUrl: 'airbnb',
    displayName: 'airbnb',
    integration: airbnbIntegration,
  },
  {
    matchUrl: 'booking',
    displayName: 'booking-com',
    integration: bookingComIntegration,
  },
];

export const getIntegrationsDisplayName = services.map((e) => e.displayName);

export const getIntegration = (name: string) =>
  services.find((s) => s.matchUrl === name || s.displayName === name)
    ?.integration;
