import { day } from '@vrplatform/utils';
import { fetchBooking } from '../fetch';

const generateCsvRequestIdMutation = () => ({
  operationName: 'generateFinancialReportMutation',
  variables: {
    input: {
      reportType: ['PAYOUT'],
      fromDate: day().subtract(2, 'month').startOf('month').yyyymmdd(),
      toDate: day().endOf('month').yyyymmdd(),
    },
  },
  extensions: {},
  query:
    'mutation generateFinancialReportMutation($input: RequestFilterInput!) {\n  generateReport(filter: $input) {\n    requestId\n    filter {\n      legalEntityIds\n      reportType\n      reportType\n      fromDate\n      toDate\n      payoutMethodReferenceIds\n      payoutType\n      __typename\n    }\n    reportStatus\n    createdAt\n    __typename\n  }\n}\n',
});

const generateCsvUrlMutation = (requestId: string) => {
  return {
    operationName: 'downloadReportQuery',
    variables: {
      requestId: requestId,
    },
    extensions: {},
    query:
      'query downloadReportQuery($requestId: ID!) {\n  downloadReport(requestId: $requestId) {\n    fileName\n    url\n    __typename\n  }\n}\n',
  };
};

export const generateCsvUrl = async ({
  requestId,
  cookieString,
  sessionId,
}: {
  requestId: string;
  cookieString: string;
  sessionId: string;
}) => {
  const mutation = generateCsvUrlMutation(requestId);

  const urlResponse = await fetchBooking(mutation, sessionId, cookieString);

  if (!urlResponse.ok) {
    throw new Error('Failed to generate url');
  }

  const urlResponseData: {
    data: { downloadReport?: { url?: string } };
  } = await urlResponse.json();

  if (!urlResponseData.data.downloadReport?.url) {
    throw new Error('No url found');
  }

  return urlResponseData.data.downloadReport.url;
};

export const generateRequestId = async ({
  cookieString,
  sessionId,
}: {
  cookieString: string;
  sessionId: string;
}) => {
  const generateRequestIdResponse = await fetchBooking(
    generateCsvRequestIdMutation(),
    sessionId,
    cookieString
  );

  console.log(generateRequestIdResponse);

  if (!generateRequestIdResponse.ok) {
    console.log(
      `Error ${generateRequestIdResponse.statusText}`,
      await generateRequestIdResponse.text()
    );
    throw new Error('Failed to generate request id');
  }

  console.log(generateRequestIdResponse.statusText);

  const generateRequestIdJson: {
    data: {
      generateReport: {
        requestId: string;
      };
    };
  } = await generateRequestIdResponse.json();

  console.log(generateRequestIdJson);

  return generateRequestIdJson.data.generateReport.requestId;
};

export async function getSinglePayout(
  sessionId: string,
  cookieString: string,
  setPayoutsData: (data: string) => void,
  setPayoutsProgress: (progress: {
    total: number;
    progress: number;
    message: string;
  }) => void
) {
  const requestId = await generateRequestId({
    cookieString,
    sessionId,
  });

  if (!requestId) {
    throw new Error('Failed to generate payouts, please refresh your screen.');
  }

  setPayoutsProgress({
    total: 1,
    progress: 0,
    message: 'Extracting payouts...',
  });

  console.log('Using requestId', requestId);

  const retryGeneratingCsv = async (
    retries = 0
  ): Promise<string | undefined> => {
    if (retries > 10) return undefined;

    try {
      return await generateCsvUrl({
        requestId,
        cookieString,
        sessionId,
      });
    } catch {
      // wait 5 sec
      await new Promise((resolve) => setTimeout(resolve, 5_000));

      return await retryGeneratingCsv(retries + 1);
    }
  };

  const csv = await retryGeneratingCsv();

  if (!csv) {
    throw new Error('Failed to generate payouts, please refresh your screen.');
  }

  setPayoutsData(csv);
}
