import type { Session } from '../types';
import { evaluateOnTab } from '../utils';
import Cookie = chrome.cookies.Cookie;

export const getSession = async (
  tabId: number
): Promise<Session | undefined> => {
  const stringifyFromWindow = (element: string) =>
    evaluateOnTab(
      tabId,
      (element: string) =>
        JSON.stringify(
          (window as unknown as { [key: string]: object })[element]
        ),
      [element]
    );

  const localStorage = await stringifyFromWindow('localStorage');
  const sessionStorage = await stringifyFromWindow('sessionStorage');

  if (!localStorage || !sessionStorage) {
    return undefined;
  }

  const locale = await evaluateOnTab(tabId, () =>
    navigator.languages?.length ? navigator.languages[0] : navigator.language
  );

  const host = await evaluateOnTab(tabId, () => document.location.host);

  if (!host || !locale) {
    return undefined;
  }

  const cookies: Cookie[] = await new Promise((resolve) =>
    chrome.cookies.getAll({}, (_cookies: Cookie[]) =>
      resolve(_cookies.filter((cookie: Cookie) => host.includes(cookie.domain)))
    )
  );

  return {
    locale,
    cookies,
    host,
    storage: {
      [host as string]: {
        localStorage: JSON.parse(localStorage as string),
        sessionStorage: JSON.parse(sessionStorage as string),
      },
    },
  };
};

export const clearSession = async (tabId?: number) => {
  if (!tabId) {
    const [currentTab] = await chrome.tabs.query({
      active: true,
      lastFocusedWindow: true,
    });
    tabId = currentTab?.id;
  }
  if (!tabId) return;
  const host = await evaluateOnTab(tabId, () => {
    window.localStorage.clear();
    window.sessionStorage.clear();
    return document.location.host;
  }, []);

  if (!host) return;
  const cookies: Cookie[] = await new Promise((resolve) =>
    chrome.cookies.getAll({}, (_cookies: Cookie[]) =>
      resolve(_cookies.filter((cookie: Cookie) => host.includes(cookie.domain)))
    )
  );
  for (const cookie of cookies) {
    await chrome.cookies.remove({
      name: cookie.name,
      url: extrapolateUrlFromCookie(cookie),
      storeId: cookie.storeId,
    });
  }
  await evaluateOnTab(tabId, () => {
    window.location.reload();
  }, []);
};

function extrapolateUrlFromCookie(cookie: Cookie) {
  let prefix = cookie.secure ? 'https://' : 'http://';
  if (cookie.domain.charAt(0) === '.') prefix += 'www';

  return prefix + cookie.domain + cookie.path;
}
