export const evaluateOnTab = <U>(
  tabId: number,
  func: (...args: any) => U,
  args: any = undefined // No solution to type this one, as it uses internal Args chrome type
): Promise<U | undefined> => {
  return new Promise((resolve) =>
    chrome.scripting.executeScript(
      {
        func,
        args,
        target: { tabId, allFrames: true },
      },
      (result) =>
        resolve(
          result && result.length > 0
            ? (result[0].result as Awaited<U>)
            : undefined
        )
    )
  );
};
